import MaterialIcons from "@expo/vector-icons/MaterialIcons";
import { useFocusEffect, useRouter } from "expo-router";
import { useCallback, useEffect, useMemo, useRef, useState, type RefObject } from "react";
import { ActivityIndicator, Alert, Modal, Platform, ScrollView, StyleSheet, Switch, TextInput, TouchableOpacity, View } from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";

import { ScaledText } from "@/components/focus-flow/scaled-text";
import { COLORS, LoadingScreen, ScreenHeading } from "@/components/focus-flow/ui";
import { ScreenContainer } from "@/components/screen-container";
import { getAccessibilityStatus, getGateDiagnostics, getLaunchableApps, isNativeGateAvailable, openAccessibilitySettings, openAppDetailsSettings, type GateDiagnostics, type LaunchableApp } from "@/lib/focus-flow/android-gate";
import { APP_FONT_OPTIONS, getAppFontStyle } from "@/lib/focus-flow/app-fonts";
import { APPEARANCE_OPTIONS, APP_THEMES, resolvedAppTheme } from "@/lib/focus-flow/app-themes";
import { isEnglish } from "@/lib/focus-flow/i18n";
import { useFocusFlow } from "@/lib/focus-flow/provider";
import { cancelDailyReminder, getReminderPermissionGranted, requestReminderPermission, scheduleDailyReminder, sendReminderTest } from "@/lib/focus-flow/reminders";
import type { AppThemeId, DisplaySettings, GateSchedule, SavedThemeSet, WidgetAccentTheme, WidgetBackgroundTheme, WidgetTextSize, WidgetThemeKind } from "@/lib/focus-flow/types";
import { getGateSummary, isGateTimeActive } from "@/lib/focus-flow/utils";
import { getWidgetTheme, WIDGET_ACCENT_OPTIONS, WIDGET_ACCENT_SWATCH, WIDGET_BACKGROUND_OPTIONS, WIDGET_BACKGROUND_SWATCH, WIDGET_THEME_KINDS } from "@/lib/focus-flow/widget-themes";

const Text = ScaledText;
type SettingsPanel = "home" | "limits" | "appearance" | "reminders" | "widgets" | "plus";

export default function SettingsScreen() {
  const router = useRouter();
  const insets = useSafeAreaInsets();
  const { todos, habits, memos, focusSessions, gateConfig, displaySettings, isReady, setGateConfig, canSelectBlockedApp, setDisplaySettings, plusStatus, purchasePlus, restorePlus, refreshPlusStatus, managePlus } = useFocusFlow();
  const [panel, setPanel] = useState<SettingsPanel>("home");
  const [apps, setApps] = useState<LaunchableApp[]>([]);
  const [nativeReady, setNativeReady] = useState(false);
  const [accessibilityEnabled, setAccessibilityEnabled] = useState(false);
  const [diagnostics, setDiagnostics] = useState<GateDiagnostics>();
  const [loadingApps, setLoadingApps] = useState(false);
  const [appPickerOpen, setAppPickerOpen] = useState(false);
  const [routineOpenId, setRoutineOpenId] = useState<string>();
  const [widgetOpen, setWidgetOpen] = useState<WidgetThemeKind>();
  const [disclosureOpen, setDisclosureOpen] = useState(false);
  const [reminderPermission, setReminderPermission] = useState(false);
  const [reminderBusy, setReminderBusy] = useState(false);
  const [themeSetName, setThemeSetName] = useState("");
  const homeScrollRef = useRef<ScrollView>(null);

  const english = isEnglish(displaySettings);
  const t = (ja: string, en: string) => english ? en : ja;
  const isIOS = Platform.OS === "ios";
  const isPlus = Boolean(displaySettings.plusEntitlement && plusStatus.active);
  const summary = useMemo(() => getGateSummary({ todos, habits, memos, focusSessions, gateConfig, displaySettings }, new Date(), english ? "en" : "ja"), [todos, habits, memos, focusSessions, gateConfig, displaySettings, english]);
  const scheduleActive = useMemo(() => isGateTimeActive(gateConfig), [gateConfig]);

  const loadAndroidStatus = useCallback(async () => {
    const available = Platform.OS === "android" && isNativeGateAvailable();
    setNativeReady(available);
    if (!available) return;
    setLoadingApps(true);
    try {
      const [status, installed, currentDiagnostics] = await Promise.all([getAccessibilityStatus(), getLaunchableApps(), getGateDiagnostics()]);
      setAccessibilityEnabled(status);
      setApps(installed);
      setDiagnostics(currentDiagnostics);
    } finally {
      setLoadingApps(false);
    }
  }, []);

  useEffect(() => { void loadAndroidStatus(); }, [loadAndroidStatus]);
  useEffect(() => { void getReminderPermissionGranted().then(setReminderPermission).catch(() => setReminderPermission(false)); }, []);
  useFocusEffect(useCallback(() => {
    setPanel("home");
    setAppPickerOpen(false);
    setRoutineOpenId(undefined);
    setWidgetOpen(undefined);
    requestAnimationFrame(() => homeScrollRef.current?.scrollTo({ y: 0, animated: false }));
    return undefined;
  }, []));

  if (!isReady) return <ScreenContainer><LoadingScreen /></ScreenContainer>;

  const setGateEnabled = (enabled: boolean) => {
    if (isIOS || !enabled) { setGateConfig({ enabled }); return; }
    if (!gateConfig.accessibilityDisclosureAcceptedAt) { setDisclosureOpen(true); return; }
    setGateConfig({ enabled: true });
  };
  const enableAndOpenAccessibility = async () => {
    if (!gateConfig.accessibilityDisclosureAcceptedAt) setGateConfig({ accessibilityDisclosureAcceptedAt: new Date().toISOString() });
    await openAccessibilitySettings();
    setTimeout(() => void loadAndroidStatus(), 900);
  };
  const acceptDisclosure = () => {
    setGateConfig({ enabled: true, accessibilityDisclosureAcceptedAt: new Date().toISOString() });
    setDisclosureOpen(false);
    void openAccessibilitySettings();
  };
  const selectGlobalApp = (packageName: string) => {
    const selected = gateConfig.blockedPackages.includes(packageName);
    if (!selected && !canSelectBlockedApp(packageName)) {
      Alert.alert(t("無料版の上限です", "Free plan limit"), t("無料版では制限対象アプリを5件まで選べます。Plusでは無制限です。", "The free plan allows 5 limited apps. Plus removes this limit."));
      return;
    }
    setGateConfig({ blockedPackages: selected ? gateConfig.blockedPackages.filter((item) => item !== packageName) : [...gateConfig.blockedPackages, packageName] });
  };
  const addSchedule = () => setGateConfig({ schedules: [...gateConfig.schedules, { id: `schedule-${Date.now()}`, label: t(`日課 ${gateConfig.schedules.length + 1}`, `Routine ${gateConfig.schedules.length + 1}`), enabled: true, days: [1, 2, 3, 4, 5], startTime: "09:00", endTime: "18:00", requiredTodoIds: [], requiredHabitIds: [], blockedPackages: [] }] });
  const updateSchedule = (id: string, input: Partial<GateSchedule>) => setGateConfig({ schedules: gateConfig.schedules.map((item) => item.id === id ? { ...item, ...input } : item) });
  const removeSchedule = (id: string) => setGateConfig({ schedules: gateConfig.schedules.filter((item) => item.id !== id) });
  const toggleReminder = async (enabled: boolean) => {
    if (Platform.OS === "web") return;
    setReminderBusy(true);
    try {
      if (!enabled) { await cancelDailyReminder(); setDisplaySettings({ dailyReminderEnabled: false }); return; }
      const permitted = await requestReminderPermission();
      setReminderPermission(permitted);
      if (permitted) setDisplaySettings({ dailyReminderEnabled: await scheduleDailyReminder({ english, time: displaySettings.dailyReminderTime ?? "19:00" }) });
    } finally { setReminderBusy(false); }
  };
  const updateReminderTime = async (time: string) => {
    setDisplaySettings({ dailyReminderTime: time });
    if (!displaySettings.dailyReminderEnabled) return;
    setReminderBusy(true);
    try { setReminderPermission(await scheduleDailyReminder({ english, time })); } finally { setReminderBusy(false); }
  };
  const setWidgetTheme = (kind: WidgetThemeKind, input: Partial<{ background: WidgetBackgroundTheme; accent: WidgetAccentTheme }>) => {
    const current = getWidgetTheme(displaySettings, kind);
    setDisplaySettings({ widgetThemes: { ...(displaySettings.widgetThemes ?? {}), [kind]: { ...current, ...input } } });
  };
  const setWidgetTextSize = (kind: WidgetThemeKind, textSize: WidgetTextSize) => setDisplaySettings({ widgetTextSizes: { ...(displaySettings.widgetTextSizes ?? {}), [kind]: textSize } });
  const resetWidgetTheme = (kind: WidgetThemeKind) => { const widgetThemes = { ...(displaySettings.widgetThemes ?? {}) }; delete widgetThemes[kind]; setDisplaySettings({ widgetThemes }); };
  const saveThemeSet = () => {
    const name = themeSetName.trim();
    if (!isPlus || !name) return;
    const set: SavedThemeSet = { id: `theme-set-${Date.now()}`, name: name.slice(0, 32), appTheme: resolvedAppTheme(displaySettings), appearance: displaySettings.appearance ?? "system", fontFamily: displaySettings.fontFamily ?? "system", widgetThemes: displaySettings.widgetThemes ?? {}, widgetTextSizes: displaySettings.widgetTextSizes ?? {} };
    setDisplaySettings({ savedThemeSets: [...(displaySettings.savedThemeSets ?? []), set] });
    setThemeSetName("");
  };

  const body = panel === "home" ? (
    <SettingsHome scrollRef={homeScrollRef} english={english} gateEnabled={gateConfig.enabled} pendingCount={summary.pendingCount} accessibilityEnabled={accessibilityEnabled} themeLabel={english ? APP_THEMES[resolvedAppTheme(displaySettings)].label.en : APP_THEMES[resolvedAppTheme(displaySettings)].label.ja} languageLabel={displaySettings.language === "en" ? "English" : displaySettings.language === "ja" ? "日本語" : t("端末に連動", "Automatic")} reminderEnabled={Boolean(displaySettings.dailyReminderEnabled)} isPlus={isPlus} onOpen={setPanel} onLegal={(path) => router.push(path as never)} />
  ) : (
    <ScrollView key={panel} contentContainerStyle={[styles.detailContent, { paddingBottom: Math.max(88, insets.bottom + 44) }]} showsVerticalScrollIndicator={false}>
      <PanelHeader title={panel === "limits" ? t("集中制限", "App limits") : panel === "appearance" ? t("表示と言語", "Appearance & language") : panel === "reminders" ? t("毎日のリマインダー", "Daily reminder") : panel === "widgets" ? t("ホーム画面ウィジェット", "Home screen widgets") : t("Plusとサブスクリプション", "Plus & subscription")} onBack={() => setPanel("home")} />
      {panel === "limits" ? <LimitsPanel english={english} isIOS={isIOS} nativeReady={nativeReady} loadingApps={loadingApps} apps={apps} appPickerOpen={appPickerOpen} onToggleAppPicker={() => setAppPickerOpen((value) => !value)} selectedApps={gateConfig.blockedPackages} onSelectApp={selectGlobalApp} enabled={gateConfig.enabled} pendingCount={summary.pendingCount} scheduleActive={scheduleActive} autoRequireDueToday={gateConfig.autoRequireDueToday} accessibilityEnabled={accessibilityEnabled} diagnostics={diagnostics} schedules={gateConfig.schedules} routineOpenId={routineOpenId} onToggleEnabled={setGateEnabled} onToggleDueToday={(autoRequireDueToday) => setGateConfig({ autoRequireDueToday })} onOpenAccessibility={() => void enableAndOpenAccessibility()} onRefresh={() => void loadAndroidStatus()} onOpenAppInfo={() => void openAppDetailsSettings()} onAddSchedule={addSchedule} onToggleRoutine={setRoutineOpenId} onUpdateSchedule={updateSchedule} onRemoveSchedule={removeSchedule} canSelectBlockedApp={canSelectBlockedApp} /> : null}
      {panel === "appearance" ? <AppearancePanel english={english} displaySettings={displaySettings} onChange={setDisplaySettings} /> : null}
      {panel === "reminders" ? <ReminderPanel english={english} enabled={Boolean(displaySettings.dailyReminderEnabled)} permission={reminderPermission} time={displaySettings.dailyReminderTime ?? "19:00"} busy={reminderBusy} onToggle={(enabled) => void toggleReminder(enabled)} onChangeTime={(time) => void updateReminderTime(time)} onTest={() => void (async () => { setReminderBusy(true); try { setReminderPermission((await sendReminderTest(english)) || reminderPermission); } finally { setReminderBusy(false); } })()} /> : null}
      {panel === "widgets" ? <WidgetsPanel english={english} displaySettings={displaySettings} openKind={widgetOpen} onToggle={setWidgetOpen} onBackground={(kind, background) => setWidgetTheme(kind, { background })} onAccent={(kind, accent) => setWidgetTheme(kind, { accent })} onTextSize={setWidgetTextSize} onReset={resetWidgetTheme} /> : null}
      {panel === "plus" ? <PlusPanel english={english} isIOS={isIOS} isPlus={isPlus} price={plusStatus.price} status={plusStatus.status} reason={plusStatus.reason} themeSetName={themeSetName} themeSets={displaySettings.savedThemeSets ?? []} onNameChange={setThemeSetName} onSaveSet={saveThemeSet} onApplySet={(set) => setDisplaySettings({ appTheme: set.appTheme, appearance: set.appearance, fontFamily: set.fontFamily ?? "system", widgetThemes: set.widgetThemes, widgetTextSizes: set.widgetTextSizes })} onRemoveSet={(id) => setDisplaySettings({ savedThemeSets: (displaySettings.savedThemeSets ?? []).filter((set) => set.id !== id) })} onPurchase={() => void purchasePlus()} onRestore={() => void restorePlus()} onRefresh={() => void refreshPlusStatus()} onManage={() => void managePlus()} /> : null}
    </ScrollView>
  );

  return <ScreenContainer className="px-5" containerClassName="bg-background">
    <Modal visible={disclosureOpen} transparent animationType="fade" onRequestClose={() => setDisclosureOpen(false)}><View style={styles.modalBackdrop}><View style={styles.modalCard}><MaterialIcons name="privacy-tip" size={25} color={COLORS.blue} /><Text style={styles.modalTitle}>{t("集中制限を有効にする前に", "Before turning on App limits")}</Text><Text style={styles.modalText}>{t("Focus Flowは選択したアプリが前面に開いたことだけを確認し、未完了の必須項目がある間に集中ルールを適用します。画面の内容・メッセージ・入力内容・スクリーンショットは読み取りません。", "Focus Flow only checks when a selected app comes to the foreground and applies your rule while must-dos remain. It does not read screen content, messages, typed text, or screenshots.")}</Text><TouchableOpacity onPress={acceptDisclosure} style={styles.primaryButton}><Text style={styles.primaryButtonText}>{t("内容を理解してAndroidの設定を開く", "I understand — open Android settings")}</Text></TouchableOpacity><TouchableOpacity onPress={() => setDisclosureOpen(false)} style={styles.textButton}><Text style={styles.textButtonLabel}>{t("今は設定しない", "Not now")}</Text></TouchableOpacity></View></View></Modal>
    {body}
  </ScreenContainer>;
}

function SettingsHome({ scrollRef, english, gateEnabled, pendingCount, accessibilityEnabled, themeLabel, languageLabel, reminderEnabled, isPlus, onOpen, onLegal }: { scrollRef: RefObject<ScrollView | null>; english: boolean; gateEnabled: boolean; pendingCount: number; accessibilityEnabled: boolean; themeLabel: string; languageLabel: string; reminderEnabled: boolean; isPlus: boolean; onOpen: (panel: SettingsPanel) => void; onLegal: (path: string) => void }) {
  const t = (ja: string, en: string) => english ? en : ja;
  const limitDetail = !gateEnabled ? t("オフ", "Off") : pendingCount ? t(`制限中・未完了 ${pendingCount}件`, `On · ${pendingCount} open`) : t("有効・解除条件を完了", "On · all clear");
  return <ScrollView ref={scrollRef} contentContainerStyle={styles.homeContent} showsVerticalScrollIndicator={false}>
    <ScreenHeading eyebrow={t("自分に合わせる", "Make it yours")} title={t("設定", "Settings")} />
    <Text style={styles.homeLead}>{t("よく使う設定だけを先に表示しています。目的を選ぶと、その項目だけを開きます。", "Only the essentials are shown first. Choose a purpose to open its details.")}</Text>
    <SettingsEntry icon="lock-outline" tint="#FFF4E3" color="#A56812" title={t("集中制限", "App limits")} detail={limitDetail} badge={!accessibilityEnabled && gateEnabled ? t("許可が必要", "Permission needed") : undefined} onPress={() => onOpen("limits")} />
    <SettingsEntry icon="palette" tint="#E4F3EF" color={COLORS.forest} title={t("表示と言語", "Appearance & language")} detail={`${themeLabel} · ${languageLabel}`} onPress={() => onOpen("appearance")} />
    <SettingsEntry icon="notifications-none" tint="#E9F3FA" color={COLORS.blue} title={t("毎日のリマインダー", "Daily reminder")} detail={reminderEnabled ? t("オン", "On") : t("オフ", "Off")} onPress={() => onOpen("reminders")} />
    <SettingsEntry icon="widgets" tint="#F0F5E9" color={COLORS.forest} title={t("ホーム画面ウィジェット", "Home screen widgets")} detail={t("見た目をまとめて調整", "Adjust widget appearance")} onPress={() => onOpen("widgets")} />
    <SettingsEntry icon="workspace-premium" tint="#F5ECFB" color="#74509B" title={t("Plusとサブスクリプション", "Plus & subscription")} detail={isPlus ? t("Plusを利用中", "Plus is active") : t("無料版の範囲とPlusを確認", "Review Free and Plus")} onPress={() => onOpen("plus")} />
    <View style={styles.supportLinks}><TouchableOpacity onPress={() => onLegal("/privacy")}><Text style={styles.supportLink}>{t("プライバシー", "Privacy")}</Text></TouchableOpacity><TouchableOpacity onPress={() => onLegal("/legal")}><Text style={styles.supportLink}>{t("利用条件", "Terms")}</Text></TouchableOpacity><TouchableOpacity onPress={() => onLegal("/support")}><Text style={styles.supportLink}>{t("サポート", "Support")}</Text></TouchableOpacity></View>
  </ScrollView>;
}

function LimitsPanel({ english, isIOS, nativeReady, loadingApps, apps, appPickerOpen, onToggleAppPicker, selectedApps, onSelectApp, enabled, pendingCount, scheduleActive, autoRequireDueToday, accessibilityEnabled, diagnostics, schedules, routineOpenId, onToggleEnabled, onToggleDueToday, onOpenAccessibility, onRefresh, onOpenAppInfo, onAddSchedule, onToggleRoutine, onUpdateSchedule, onRemoveSchedule, canSelectBlockedApp }: { english: boolean; isIOS: boolean; nativeReady: boolean; loadingApps: boolean; apps: LaunchableApp[]; appPickerOpen: boolean; onToggleAppPicker: () => void; selectedApps: string[]; onSelectApp: (value: string) => void; enabled: boolean; pendingCount: number; scheduleActive: boolean; autoRequireDueToday: boolean; accessibilityEnabled: boolean; diagnostics?: GateDiagnostics; schedules: GateSchedule[]; routineOpenId?: string; onToggleEnabled: (value: boolean) => void; onToggleDueToday: (value: boolean) => void; onOpenAccessibility: () => void; onRefresh: () => void; onOpenAppInfo: () => void; onAddSchedule: () => void; onToggleRoutine: (id?: string) => void; onUpdateSchedule: (id: string, input: Partial<GateSchedule>) => void; onRemoveSchedule: (id: string) => void; canSelectBlockedApp: (packageName: string) => boolean }) {
  const t = (ja: string, en: string) => english ? en : ja;
  if (isIOS) return <InfoCard icon="phone-iphone" title={t("iPhoneではアプリ制限を使いません", "App limits are not available on iPhone")} detail={t("Todo・習慣・時間管理・通知は追加権限なしで利用できます。", "Tasks, habits, timed items, and reminders work without extra device permission.")} />;
  return <>
    <InfoCard icon={enabled && pendingCount ? "lock" : "lock-open"} title={enabled ? pendingCount ? t(`現在 ${pendingCount}件の必須項目が未完了です`, `${pendingCount} must-do item(s) are open`) : t("集中制限は有効です", "App limits are on") : t("集中制限はオフです", "App limits are off")} detail={enabled ? scheduleActive ? t("選択したアプリは、必須項目を完了するまで制限されます。", "Selected apps stay limited until must-dos are complete.") : t("現在は設定した時間帯の外です。", "The current time is outside your schedule.") : t("オンにすると、選択したアプリを必須項目の完了まで制限します。", "Turn this on to limit selected apps until must-dos are complete.")} />
    <View style={styles.card}><SettingRow title={t("必須項目を終えるまで制限", "Limit apps until must-dos are done")} detail={t("オンにする前に、Androidのアクセシビリティ許可を確認します。", "Android Accessibility permission is checked before enabling.")} control={<Switch value={enabled} onValueChange={onToggleEnabled} trackColor={{ false: "#CCD7D1", true: "#91C3B3" }} thumbColor={enabled ? COLORS.forest : "#F7F8F5"} />} /><SettingRow title={t("期限当日のTodoを必須にする", "Make due-today tasks must-dos")} detail={t("未完了の期限当日Todoを解除条件へ自動追加します。", "Adds unfinished due-today tasks to unlock conditions.")} control={<Switch value={autoRequireDueToday} onValueChange={onToggleDueToday} trackColor={{ false: "#CCD7D1", true: "#91C3B3" }} thumbColor={autoRequireDueToday ? COLORS.forest : "#F7F8F5"} />} /></View>
    <SectionTitle title={t("Androidの許可と状態", "Android permission & status")} />
    <View style={styles.card}><SettingRow title={accessibilityEnabled ? t("アクセシビリティは有効です", "Accessibility is enabled") : t("アクセシビリティを許可する", "Allow Accessibility")} detail={accessibilityEnabled ? t("選択アプリの前面化を検出できます。", "Focus Flow can detect selected apps in the foreground.") : t("許可されない限り、アプリ制限は動作しません。", "App limits cannot run until this is enabled.")} control={<TouchableOpacity onPress={onOpenAccessibility} style={styles.smallButton}><Text style={styles.smallButtonText}>{accessibilityEnabled ? t("開く", "Open") : t("許可", "Allow")}</Text></TouchableOpacity>} /><View style={styles.compactStatus}><MaterialIcons name={diagnostics?.backgroundRestricted ? "warning-amber" : "check-circle"} size={16} color={diagnostics?.backgroundRestricted ? COLORS.warning : COLORS.success} /><Text style={styles.compactStatusText}>{diagnostics?.backgroundRestricted ? t("バックグラウンド実行が制限されています。端末のアプリ情報で許可してください。", "Background activity is restricted. Allow it in app info.") : t("バックグラウンド実行に大きな制限は検出されませんでした。", "No major background restriction was detected.")}</Text></View><View style={styles.inlineActions}><TouchableOpacity onPress={onRefresh} style={styles.textAction}><Text style={styles.textActionLabel}>{t("状態を再確認", "Refresh status")}</Text></TouchableOpacity><TouchableOpacity onPress={onOpenAppInfo} style={styles.textAction}><Text style={styles.textActionLabel}>{t("アプリ情報", "App info")}</Text></TouchableOpacity></View></View>
    <SectionTitle title={t("制限するアプリ", "Apps to limit")} detail={t("ここで選んだアプリは、設定した時間帯のすべてで制限対象になります。", "Apps selected here are limited in every active schedule.")} />
    <View style={styles.card}><TouchableOpacity onPress={onToggleAppPicker} style={styles.selectorRow}><View style={styles.selectorIcon}><MaterialIcons name="apps" size={20} color={COLORS.forest} /></View><View style={styles.selectorCopy}><Text style={styles.selectorTitle}>{selectedApps.length ? t(`${selectedApps.length}件を選択中`, `${selectedApps.length} selected`) : t("アプリを選ぶ", "Choose apps")}</Text><Text style={styles.selectorDetail}>{t("銀行・決済・連絡・地図アプリは選ばないでください。", "Do not select banking, payment, messaging, or navigation apps.")}</Text></View><MaterialIcons name={appPickerOpen ? "expand-less" : "chevron-right"} size={22} color={COLORS.muted} /></TouchableOpacity>{appPickerOpen ? <AppPicker apps={apps} loading={loadingApps} selected={selectedApps} onSelect={onSelectApp} canSelect={canSelectBlockedApp} english={english} /> : null}</View>
    <SectionTitle title={t("時間帯", "Schedules")} detail={t("時間帯を設定しない場合は常時適用です。", "Without a schedule, limits are always active.")} />
    <View style={styles.card}>{schedules.map((schedule) => <RoutineEditor key={schedule.id} schedule={schedule} expanded={routineOpenId === schedule.id} apps={apps} loading={loadingApps} english={english} onToggle={() => onToggleRoutine(routineOpenId === schedule.id ? undefined : schedule.id)} onChange={(input) => onUpdateSchedule(schedule.id, input)} onRemove={() => onRemoveSchedule(schedule.id)} />)}<TouchableOpacity onPress={onAddSchedule} style={styles.addButton}><MaterialIcons name="add" size={18} color={COLORS.forest} /><Text style={styles.addButtonText}>{t("時間帯を追加", "Add a schedule")}</Text></TouchableOpacity></View>
  </>;
}

function AppearancePanel({ english, displaySettings, onChange }: { english: boolean; displaySettings: DisplaySettings; onChange: (input: Partial<DisplaySettings>) => void }) {
  const t = (ja: string, en: string) => english ? en : ja;
  return <>
    <InfoCard icon="palette" title={t("表示を自分に合わせる", "Make the display yours")} detail={t("配色、文字、言語をまとめて調整できます。すべて無料で利用できます。", "Adjust color, type, and language together. Every option is free.")} />
    <SectionTitle title={t("アプリの配色", "App color")} />
    <View style={styles.choiceGrid}>{(Object.keys(APP_THEMES) as AppThemeId[]).map((theme) => <ThemeChoice key={theme} theme={theme} selected={resolvedAppTheme(displaySettings) === theme} english={english} onPress={() => onChange({ appTheme: theme })} />)}</View>
    <SectionTitle title={t("外観モード", "Appearance mode")} />
    <Segmented options={APPEARANCE_OPTIONS.map((item) => ({ key: item, label: item === "system" ? t("端末に連動", "System") : item === "light" ? t("ライト", "Light") : t("ダーク", "Dark") }))} selected={displaySettings.appearance ?? "system"} onSelect={(appearance) => onChange({ appearance: appearance as DisplaySettings["appearance"] })} />
    <SectionTitle title={t("フォント", "Font")} detail={t("同じ文で見比べて選べます。", "Compare every choice using the same sentence.")} />
    <View style={styles.fontGrid}>{APP_FONT_OPTIONS.map((item) => <TouchableOpacity key={item.id} onPress={() => onChange({ fontFamily: item.id })} style={[styles.fontChoice, (displaySettings.fontFamily ?? "system") === item.id && styles.selectedChoice]}><Text style={[styles.fontSample, getAppFontStyle(item.id)]}>{english ? item.sample.en : item.sample.ja}</Text><Text style={styles.choiceLabel}>{english ? item.label.en : item.label.ja}</Text></TouchableOpacity>)}</View>
    <SectionTitle title={t("文字サイズ", "Text size")} /><Segmented options={[{ key: "compact", label: t("小さめ", "Compact") }, { key: "standard", label: t("標準", "Standard") }, { key: "large", label: t("大きめ", "Large") }]} selected={displaySettings.fontScale} onSelect={(fontScale) => onChange({ fontScale: fontScale as DisplaySettings["fontScale"] })} />
    <SectionTitle title={t("カードの見え方", "Card surface")} /><Segmented options={[{ key: "solid", label: t("不透明", "Solid") }, { key: "soft", label: t("やわらかく", "Soft") }, { key: "glass", label: t("ガラス", "Glass") }]} selected={displaySettings.cardOpacity} onSelect={(cardOpacity) => onChange({ cardOpacity: cardOpacity as DisplaySettings["cardOpacity"] })} />
    <SectionTitle title={t("言語 / Language", "Language")} detail={t("自動では端末の言語を使います。日本語端末では日本語で表示されます。", "Automatic follows your device language.")} /><Segmented options={[{ key: "auto", label: t("自動", "Automatic") }, { key: "ja", label: "日本語" }, { key: "en", label: "English" }]} selected={displaySettings.language ?? "auto"} onSelect={(language) => onChange({ language: language as DisplaySettings["language"] })} />
  </>;
}

function ReminderPanel({ english, enabled, permission, time, busy, onToggle, onChangeTime, onTest }: { english: boolean; enabled: boolean; permission: boolean; time: string; busy: boolean; onToggle: (value: boolean) => void; onChangeTime: (value: string) => void; onTest: () => void }) {
  const t = (ja: string, en: string) => english ? en : ja;
  return <><InfoCard icon="notifications-none" title={t("1日1回だけの確認", "One gentle daily check-in")} detail={t("完了状況を問わず、今日の予定を確認するための中立的な通知です。", "A neutral reminder to review today, regardless of completion.")} /><View style={styles.card}><SettingRow title={t("日課を確認する", "Daily check-in")} detail={permission ? t("通知は許可されています。", "Notifications are allowed.") : t("オンにすると端末の通知許可を確認します。", "Turning this on requests notification permission.")} control={<Switch value={enabled} disabled={busy} onValueChange={onToggle} trackColor={{ false: "#CCD7D1", true: "#91C3B3" }} thumbColor={enabled ? COLORS.forest : "#F7F8F5"} />}/>{enabled ? <><TimeStepper value={time} english={english} onChange={onChangeTime} /><TouchableOpacity disabled={busy} onPress={onTest} style={styles.primaryButton}><Text style={styles.primaryButtonText}>{busy ? t("準備中…", "Preparing…") : t("今すぐ試す", "Send a test")}</Text></TouchableOpacity></> : null}</View></>;
}

function WidgetsPanel({ english, displaySettings, openKind, onToggle, onBackground, onAccent, onTextSize, onReset }: { english: boolean; displaySettings: DisplaySettings; openKind?: WidgetThemeKind; onToggle: (value?: WidgetThemeKind) => void; onBackground: (kind: WidgetThemeKind, value: WidgetBackgroundTheme) => void; onAccent: (kind: WidgetThemeKind, value: WidgetAccentTheme) => void; onTextSize: (kind: WidgetThemeKind, value: WidgetTextSize) => void; onReset: (kind: WidgetThemeKind) => void }) {
  const t = (ja: string, en: string) => english ? en : ja;
  const names: Record<WidgetThemeKind, [string, string]> = { overview: ["概要", "Overview"], progress: ["解除の進捗", "Unlock progress"], next: ["次の必須項目", "Next must-do"], habit: ["習慣の記録", "Habit pulse"], routine: ["日課の状態", "Routine status"] };
  return <><InfoCard icon="widgets" title={t("ホーム画面に追加できる5種類", "Five widgets for your home screen")} detail={t("必要なウィジェットだけを開いて、背景・アクセント・文字サイズを調整できます。", "Open only the widget you use to adjust its background, accent, and text size.")} /><View style={styles.card}>{WIDGET_THEME_KINDS.map((kind) => { const theme = getWidgetTheme(displaySettings, kind); const open = openKind === kind; return <View key={kind} style={styles.widgetRow}><TouchableOpacity onPress={() => onToggle(open ? undefined : kind)} style={styles.selectorRow}><View style={[styles.selectorIcon, { backgroundColor: WIDGET_BACKGROUND_SWATCH[theme.background] }]}><View style={[styles.colorDot, { backgroundColor: WIDGET_ACCENT_SWATCH[theme.accent] }]} /></View><View style={styles.selectorCopy}><Text style={styles.selectorTitle}>{english ? names[kind][1] : names[kind][0]}</Text><Text style={styles.selectorDetail}>{t("見た目を調整", "Adjust appearance")}</Text></View><MaterialIcons name={open ? "expand-less" : "chevron-right"} size={22} color={COLORS.muted} /></TouchableOpacity>{open ? <View style={styles.widgetEditor}><Text style={styles.microLabel}>{t("背景", "Background")}</Text><ColorGrid values={WIDGET_BACKGROUND_OPTIONS} selected={theme.background} swatches={WIDGET_BACKGROUND_SWATCH} onSelect={(value) => onBackground(kind, value)} /><Text style={styles.microLabel}>{t("アクセント", "Accent")}</Text><ColorGrid values={WIDGET_ACCENT_OPTIONS} selected={theme.accent} swatches={WIDGET_ACCENT_SWATCH} onSelect={(value) => onAccent(kind, value)} /><Text style={styles.microLabel}>{t("文字サイズ", "Text size")}</Text><Segmented options={[{ key: "compact", label: t("小さめ", "Compact") }, { key: "standard", label: t("標準", "Standard") }, { key: "large", label: t("大きめ", "Large") }]} selected={displaySettings.widgetTextSizes?.[kind] ?? "standard"} onSelect={(value) => onTextSize(kind, value as WidgetTextSize)} /><TouchableOpacity onPress={() => onReset(kind)} style={styles.textAction}><Text style={styles.textActionLabel}>{t("このウィジェットをリセット", "Reset this widget")}</Text></TouchableOpacity></View> : null}</View>; })}</View></>;
}

function PlusPanel({ english, isIOS, isPlus, price, status, reason, themeSetName, themeSets, onNameChange, onSaveSet, onApplySet, onRemoveSet, onPurchase, onRestore, onRefresh, onManage }: { english: boolean; isIOS: boolean; isPlus: boolean; price?: string; status: string; reason?: string; themeSetName: string; themeSets: SavedThemeSet[]; onNameChange: (value: string) => void; onSaveSet: () => void; onApplySet: (set: SavedThemeSet) => void; onRemoveSet: (id: string) => void; onPurchase: () => void; onRestore: () => void; onRefresh: () => void; onManage: () => void }) {
  const t = (ja: string, en: string) => english ? en : ja;
  const storeName = isIOS ? "App Store" : "Google Play";
  return <><InfoCard icon="workspace-premium" title={isPlus ? t("Plusを利用中です", "Plus is active") : t("必要になったらPlusへ", "Upgrade only when useful")} detail={isPlus ? t("件数の上限がなく、現在の見た目をテーマセットとして保存できます。", "Item limits are removed and you can save theme sets.") : t("無料版はTodo・習慣・メモを各2件、制限対象アプリを5件まで使えます。", "Free includes 2 tasks, habits, and notes each plus 5 limited apps.")} />
    <View style={styles.card}><View style={styles.planGrid}><PlanColumn title={t("無料", "Free")} features={[t("Todo・習慣・メモ 各2件", "2 tasks, habits & notes"), t("制限アプリ 5件", "5 limited apps"), t("言語・表示・文字", "Language, look & type")]} /><PlanColumn title="Plus" highlighted features={[t("すべて無制限", "Unlimited items"), t("テーマセットの保存", "Saved theme sets"), t("早期完了は別の商品", "Early completion is separate")]} /></View>{isPlus ? <View style={styles.inlineActions}><TouchableOpacity onPress={onManage} style={styles.smallButton}><Text style={styles.smallButtonText}>{t("管理", "Manage")}</Text></TouchableOpacity><TouchableOpacity onPress={onRestore} style={styles.textAction}><Text style={styles.textActionLabel}>{t("購入を復元", "Restore purchases")}</Text></TouchableOpacity></View> : status === "eligible" ? <><TouchableOpacity onPress={onPurchase} style={styles.primaryButton}><Text style={styles.primaryButtonText}>{price ? t(`${price} でPlusを開始`, `Get Plus for ${price}`) : t("Plusを開始", "Get Plus")}</Text></TouchableOpacity><TouchableOpacity onPress={onRestore} style={styles.textButton}><Text style={styles.textButtonLabel}>{t("以前の購入を復元", "Restore previous purchase")}</Text></TouchableOpacity></> : <><Text style={styles.mutedCopy}>{reason === "NATIVE_BUILD_REQUIRED" ? t(`${storeName}からインストールしたFocus Flowで購入できます。`, `Purchases are available in the Focus Flow build installed from ${storeName}.`) : t("ストアの商品情報を確認できません。商品登録後に再確認してください。", "Store product information is unavailable. Check again after product setup.")}</Text><TouchableOpacity onPress={onRefresh} style={styles.smallButton}><Text style={styles.smallButtonText}>{t("ストア情報を再確認", "Check store status")}</Text></TouchableOpacity></>}</View>
    {isPlus ? <><SectionTitle title={t("テーマセット", "Theme sets")} detail={t("今の配色・文字・ウィジェット設定を名前付きで保存します。", "Save the current colors, type, and widgets under a name.")} /><View style={styles.card}><View style={styles.composer}><TextInput value={themeSetName} onChangeText={onNameChange} placeholder={t("例：平日の集中", "e.g., Weekday focus")} placeholderTextColor="#8B9992" style={styles.themeInput} /><TouchableOpacity onPress={onSaveSet} style={styles.smallButton}><Text style={styles.smallButtonText}>{t("保存", "Save")}</Text></TouchableOpacity></View>{themeSets.map((set) => <View key={set.id} style={styles.savedSet}><TouchableOpacity onPress={() => onApplySet(set)} style={styles.savedSetCopy}><Text style={styles.savedSetName}>{set.name}</Text><Text style={styles.selectorDetail}>{english ? APP_THEMES[set.appTheme].label.en : APP_THEMES[set.appTheme].label.ja}</Text></TouchableOpacity><TouchableOpacity onPress={() => onRemoveSet(set.id)}><MaterialIcons name="close" size={19} color={COLORS.error} /></TouchableOpacity></View>)}</View></> : null}</>;
}

function PanelHeader({ title, onBack }: { title: string; onBack: () => void }) { return <View style={styles.panelHeader}><TouchableOpacity onPress={onBack} accessibilityLabel="Back" style={styles.backControl}><MaterialIcons name="arrow-back" size={22} color={COLORS.forest} /></TouchableOpacity><Text style={styles.panelTitle}>{title}</Text></View>; }
function SettingsEntry({ icon, tint, color, title, detail, badge, onPress }: { icon: React.ComponentProps<typeof MaterialIcons>["name"]; tint: string; color: string; title: string; detail: string; badge?: string; onPress: () => void }) { return <TouchableOpacity onPress={onPress} style={styles.entry}><View style={[styles.entryIcon, { backgroundColor: tint }]}><MaterialIcons name={icon} size={22} color={color} /></View><View style={styles.entryCopy}><View style={styles.entryTitleRow}><Text style={styles.entryTitle}>{title}</Text>{badge ? <Text style={styles.entryBadge}>{badge}</Text> : null}</View><Text style={styles.entryDetail} numberOfLines={2}>{detail}</Text></View><MaterialIcons name="chevron-right" size={23} color={COLORS.muted} /></TouchableOpacity>; }
function SectionTitle({ title, detail }: { title: string; detail?: string }) { return <View style={styles.sectionTitleWrap}><Text style={styles.sectionTitle}>{title}</Text>{detail ? <Text style={styles.sectionDetail}>{detail}</Text> : null}</View>; }
function InfoCard({ icon, title, detail }: { icon: React.ComponentProps<typeof MaterialIcons>["name"]; title: string; detail: string }) { return <View style={styles.infoCard}><View style={styles.infoIcon}><MaterialIcons name={icon} size={22} color={COLORS.forest} /></View><View style={styles.infoCopy}><Text style={styles.infoTitle}>{title}</Text><Text style={styles.infoDetail}>{detail}</Text></View></View>; }
function SettingRow({ title, detail, control }: { title: string; detail: string; control: React.ReactNode }) { return <View style={styles.settingRow}><View style={styles.settingCopy}><Text style={styles.settingTitle}>{title}</Text><Text style={styles.settingDetail}>{detail}</Text></View>{control}</View>; }
function AppPicker({ apps, loading, selected, onSelect, canSelect, english }: { apps: LaunchableApp[]; loading: boolean; selected: string[]; onSelect: (value: string) => void; canSelect: (value: string) => boolean; english: boolean }) { const t = (ja: string, en: string) => english ? en : ja; if (loading) return <View style={styles.loading}><ActivityIndicator color={COLORS.forest} /><Text style={styles.mutedCopy}>{t("アプリ一覧を読み込んでいます", "Loading apps")}</Text></View>; if (!apps.length) return <Text style={styles.mutedCopy}>{t("選択できるアプリを取得できませんでした。", "Available apps could not be loaded.")}</Text>; return <View style={styles.appList}>{apps.slice(0, 60).map((app) => { const active = selected.includes(app.packageName); return <TouchableOpacity key={app.packageName} onPress={() => onSelect(app.packageName)} style={styles.appRow}><View style={[styles.check, active && styles.checkSelected]}>{active ? <MaterialIcons name="check" size={15} color={COLORS.white} /> : null}</View><View style={styles.appCopy}><Text style={styles.appName} numberOfLines={1}>{app.label}</Text><Text style={styles.appPackage} numberOfLines={1}>{app.packageName}</Text></View>{!active && !canSelect(app.packageName) ? <MaterialIcons name="lock-outline" size={16} color={COLORS.muted} /> : null}</TouchableOpacity>; })}</View>; }
function RoutineEditor({ schedule, expanded, apps, loading, english, onToggle, onChange, onRemove }: { schedule: GateSchedule; expanded: boolean; apps: LaunchableApp[]; loading: boolean; english: boolean; onToggle: () => void; onChange: (input: Partial<GateSchedule>) => void; onRemove: () => void }) { const t = (ja: string, en: string) => english ? en : ja; const [appsOpen, setAppsOpen] = useState(false); const packages = schedule.blockedPackages ?? []; return <View style={styles.routine}><TouchableOpacity onPress={onToggle} style={styles.selectorRow}><View style={styles.selectorIcon}><MaterialIcons name="schedule" size={20} color={COLORS.forest} /></View><View style={styles.selectorCopy}><Text style={styles.selectorTitle}>{schedule.label}</Text><Text style={styles.selectorDetail}>{formatDays(schedule.days, english)} · {schedule.startTime}–{schedule.endTime}</Text></View><Switch value={schedule.enabled} onValueChange={(enabled) => onChange({ enabled })} trackColor={{ false: "#CCD7D1", true: "#91C3B3" }} thumbColor={schedule.enabled ? COLORS.forest : "#F7F8F5"} /></TouchableOpacity>{expanded ? <View style={styles.routineEditor}><TextInput value={schedule.label} onChangeText={(label) => onChange({ label })} style={styles.nameInput} placeholder={t("日課の名前", "Routine name")} /><View style={styles.dayPicker}>{["日", "月", "火", "水", "木", "金", "土"].map((label, index) => <TouchableOpacity key={`${label}-${index}`} onPress={() => onChange({ days: toggleNumber(schedule.days, index) })} style={[styles.dayChip, schedule.days.includes(index) && styles.dayChipSelected]}><Text style={[styles.dayChipText, schedule.days.includes(index) && styles.dayChipTextSelected]}>{english ? ["S", "M", "T", "W", "T", "F", "S"][index] : label}</Text></TouchableOpacity>)}</View><View style={styles.timeRow}><TimeStepper value={schedule.startTime} english={english} label={t("開始", "Start")} onChange={(startTime) => onChange({ startTime })} /><TimeStepper value={schedule.endTime} english={english} label={t("終了", "End")} onChange={(endTime) => onChange({ endTime })} /></View><TouchableOpacity onPress={() => setAppsOpen((value) => !value)} style={styles.textAction}><Text style={styles.textActionLabel}>{appsOpen ? t("この時間帯のアプリ選択を閉じる", "Hide schedule app selection") : t("この時間帯だけに追加するアプリ", "Add apps for this schedule only")}</Text></TouchableOpacity>{appsOpen ? <RoutineAppPicker apps={apps} loading={loading} selected={packages} english={english} onChange={(blockedPackages) => onChange({ blockedPackages })} /> : null}<TouchableOpacity onPress={onRemove} style={styles.deleteAction}><Text style={styles.deleteActionLabel}>{t("この時間帯を削除", "Delete this schedule")}</Text></TouchableOpacity></View> : null}</View>; }
function RoutineAppPicker({ apps, loading, selected, onChange }: { apps: LaunchableApp[]; loading: boolean; selected: string[]; english: boolean; onChange: (value: string[]) => void }) { if (loading) return <View style={styles.loading}><ActivityIndicator color={COLORS.forest} /></View>; return <View style={styles.appList}>{apps.slice(0, 60).map((app) => { const active = selected.includes(app.packageName); return <TouchableOpacity key={app.packageName} onPress={() => onChange(active ? selected.filter((item) => item !== app.packageName) : [...selected, app.packageName])} style={styles.appRow}><View style={[styles.check, active && styles.checkSelected]}>{active ? <MaterialIcons name="check" size={15} color={COLORS.white} /> : null}</View><Text style={styles.appName} numberOfLines={1}>{app.label}</Text></TouchableOpacity>; })}</View>; }
function ThemeChoice({ theme, selected, english, onPress }: { theme: AppThemeId; selected: boolean; english: boolean; onPress: () => void }) { const definition = APP_THEMES[theme]; return <TouchableOpacity onPress={onPress} style={[styles.themeChoice, selected && styles.selectedChoice]}><View style={[styles.themeSwatch, { backgroundColor: definition.light.background, borderColor: definition.light.border }]}><View style={[styles.themeAccent, { backgroundColor: definition.light.primary }]} /></View><Text style={styles.choiceLabel}>{english ? definition.label.en : definition.label.ja}</Text></TouchableOpacity>; }
function Segmented({ options, selected, onSelect }: { options: { key: string; label: string }[]; selected: string; onSelect: (value: string) => void }) { return <View style={styles.segmented}>{options.map((option) => <TouchableOpacity key={option.key} onPress={() => onSelect(option.key)} style={[styles.segment, selected === option.key && styles.segmentSelected]}><Text style={[styles.segmentText, selected === option.key && styles.segmentTextSelected]}>{option.label}</Text></TouchableOpacity>)}</View>; }
function TimeStepper({ value, label, english, onChange }: { value: string; label?: string; english: boolean; onChange: (value: string) => void }) { return <View style={styles.timeStepWrap}>{label ? <Text style={styles.microLabel}>{label}</Text> : null}<View style={styles.timeStepper}><TouchableOpacity onPress={() => onChange(stepTime(value, -30))} style={styles.timeControl}><MaterialIcons name="remove" size={18} color={COLORS.forest} /></TouchableOpacity><Text style={styles.timeValue}>{value}</Text><TouchableOpacity onPress={() => onChange(stepTime(value, 30))} style={styles.timeControl}><MaterialIcons name="add" size={18} color={COLORS.forest} /></TouchableOpacity></View></View>; }
function ColorGrid<T extends string>({ values, selected, swatches, onSelect }: { values: readonly T[]; selected: T; swatches: Record<T, string>; onSelect: (value: T) => void }) { return <View style={styles.colorGrid}>{values.map((value) => <TouchableOpacity key={value} onPress={() => onSelect(value)} style={[styles.colorOption, selected === value && styles.colorOptionSelected]}><View style={[styles.colorDot, { backgroundColor: swatches[value] }]} />{selected === value ? <MaterialIcons name="check" size={14} color={COLORS.forest} /> : null}</TouchableOpacity>)}</View>; }
function PlanColumn({ title, features, highlighted = false }: { title: string; features: string[]; highlighted?: boolean }) { return <View style={[styles.planColumn, highlighted && styles.planColumnPlus]}><Text style={styles.planTitle}>{title}</Text>{features.map((feature) => <View key={feature} style={styles.planFeature}><MaterialIcons name={highlighted ? "all-inclusive" : "check"} size={14} color={highlighted ? COLORS.forest : "#547267"} /><Text style={styles.planFeatureText}>{feature}</Text></View>)}</View>; }
function stepTime(value: string, amount: number) { const [hours, minutes] = value.split(":").map(Number); const total = (((hours * 60 + minutes + amount) % 1440) + 1440) % 1440; return `${String(Math.floor(total / 60)).padStart(2, "0")}:${String(total % 60).padStart(2, "0")}`; }
function toggleNumber(values: number[], value: number) { return values.includes(value) ? values.filter((item) => item !== value) : [...values, value].sort(); }
function formatDays(days: number[], english: boolean) { const labels = english ? ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"] : ["日", "月", "火", "水", "木", "金", "土"]; if (days.length === 7) return english ? "Every day" : "毎日"; if ([1, 2, 3, 4, 5].every((day) => days.includes(day)) && days.length === 5) return english ? "Weekdays" : "平日"; return labels.filter((_, index) => days.includes(index)).join(english ? ", " : "・") || (english ? "Choose days" : "曜日を選択"); }

